BEGIN TRY
    -- Create External Data Source for landingzone
    IF NOT EXISTS (SELECT * FROM sys.external_data_sources WHERE name = 'landingzone')
    BEGIN
        CREATE EXTERNAL DATA SOURCE [landingzone]
        WITH (
            LOCATION = 'https://wearebisynapsestorage.blob.core.windows.net/landingzone'
        );
        PRINT 'External data source [landingzone] created successfully.';
    END
    ELSE
    BEGIN
        PRINT 'External data source [landingzone] already exists.';
    END

    -- Create External Data Source for bronze
    IF NOT EXISTS (SELECT * FROM sys.external_data_sources WHERE name = 'bronze')
    BEGIN
        CREATE EXTERNAL DATA SOURCE [bronze]
