        );
        PRINT 'External data source [bronze] created successfully.';
    END
    ELSE
    BEGIN
        PRINT 'External data source [bronze] already exists.';
    END

    -- Create External Data Source for silver
    IF NOT EXISTS (SELECT * FROM sys.external_data_sources WHERE name = 'silver')
    BEGIN
        CREATE EXTERNAL DATA SOURCE [silver]
        WITH (
            LOCATION = 'https://wearebisynapsestorage.blob.core.windows.net/silver'
        );
        PRINT 'External data source [silver] created successfully.';
    END
    ELSE
    BEGIN
        PRINT 'External data source [silver] already exists.';
