    BEGIN
        PRINT 'External data source [gold] already exists.';
    END

    -- Create External File Format
    IF NOT EXISTS (SELECT * FROM sys.external_file_formats WHERE name = 'ParquetFormat')
    BEGIN
        CREATE EXTERNAL FILE FORMAT ParquetFormat
        WITH (
            FORMAT_TYPE = PARQUET
        );
        PRINT 'External file format [ParquetFormat] created successfully.';
    END
    ELSE
    BEGIN
        PRINT 'External file format [ParquetFormat] already exists.';
    END
END TRY
BEGIN CATCH
    PRINT 'Error occurred: ' + ERROR_MESSAGE();
END CATCH
